import 'dart:async';
import 'dart:io';

Future<void> main() async {
  final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 51880);
  print('Backend: http://127.0.0.1:51880/api/events');
  await for (final request in server) {
    unawaited(handle(request));
  }
}

Future<void> handle(HttpRequest request) async {
  final response = request.response;
  response.headers.set('Access-Control-Allow-Origin', '*');
  if (request.uri.path != '/api/events') {
    response.statusCode = HttpStatus.notFound;
    await response.close();
    return;
  }
  response.bufferOutput = false;
  response.headers.set('Content-Type', 'application/x-ndjson');
  response.headers.set('Cache-Control', 'no-store');
  response.headers.set('X-Accel-Buffering', 'no');
  try {
    response.write('{"type":"connected"}\n');
    await response.flush();
    // Keep the response open without filling any downstream proxy buffer.
    await Future<void>.delayed(const Duration(seconds: 30));
    await response.close();
  } catch (_) {
    // The browser aborts after receiving its first line or timing out.
  }
}
